commands.service:
shell,v2,raw:dump=$(dumpsys package com.cooper.lithic.v1acceptance.debug 2>&1); source_rc=$?; printf '%s\n' "$dump" | awk 'BEGIN {inside=0;t=0;p=0;u=0;f=0;bad=0;v="";name=""}
/DUMP TIMEOUT|Error dumping|Permission Denial/ {bad++;next}
$0=="Packages:" {inside=1;t=0;next}
inside && /^[^[:space:]]/ {inside=0;t=0}
inside && /^[[:space:]]*Package \[/ {t=0;if($0 ~ /^  Package \[com\.cooper\.lithic\.v1acceptance\.debug\] \([^)]*\):[[:space:]]*$/){p++;t=1};next}
inside && t && /^    versionName=/ {name=substr($0,index($0,"=")+1)}
inside && t && /^    User 0:/ {u++;for(i=1;i<=NF;i++){if($i ~ /^installed=/){f++;if($i=="installed=true")v="true";else if($i=="installed=false")v="false";else bad++}}}
END {printf "PACKAGE_MATCHES=%d\nUSER0_MATCHES=%d\nINSTALLED_FIELDS=%d\nINVALID_FIELDS=%d\n",p,u,f,bad;if(p==1&&u==1&&f==1&&bad==0&&v!=""){print "PACKAGE=com.cooper.lithic.v1acceptance.debug";print "USER=0";print "INSTALLED="v;print "VERSION_NAME="name}else exit 65}'; filter_rc=$?; printf 'SOURCE_EXIT=%s\nFILTER_EXIT=%s\n' "$source_rc" "$filter_rc"; if [ "$source_rc" -ne 0 ]; then exit "$source_rc"; fi; exit "$filter_rc"

